def compute(vars):
    old_zyla = vars["v1"]
    new_zyla = vars["v2"]
    old_total = vars["v3"]
    new_total = vars["v4"]

    zyla_decrease = old_zyla - new_zyla
    total_decrease = old_total - new_total

    if total_decrease == 0:
        return None

    value = (zyla_decrease / total_decrease) * 100

    return {
        "value": value,
        "trace": {
            "old_zyla_revenue": old_zyla,
            "new_zyla_revenue": new_zyla,
            "zyla_decrease": zyla_decrease,
            "old_total_revenue": old_total,
            "new_total_revenue": new_total,
            "total_decrease": total_decrease,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }

def compute(vars):
    avg_2017_2018 = (vars["v1"] + vars["v2"]) / 2
    avg_2018_2019 = (vars["v3"] + vars["v4"]) / 2
    change = avg_2018_2019 - avg_2017_2018

    return {
        "value": change,
        "trace": {
            "average_2017_2018": avg_2017_2018,
            "average_2018_2019": avg_2018_2019,
            "change": change,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }

def compute(vars):
    net_2018 = vars["v1"]
    accumulated_depreciation_2018 = vars["v2"]
    net_2019 = vars["v3"]
    accumulated_depreciation_2019 = vars["v4"]

    if accumulated_depreciation_2018 == 0 or accumulated_depreciation_2019 == 0:
        return {
            "value": None,
            "trace": {
                "reason": "Division by zero while calculating yearly ratios.",
                "output_meta": {"currency": None, "scale": None, "unit": "percentage"},
            },
        }

    ratio_2018 = net_2018 / accumulated_depreciation_2018
    ratio_2019 = net_2019 / accumulated_depreciation_2019

    if ratio_2018 == 0:
        return {
            "value": None,
            "trace": {
                "ratio_2018": ratio_2018,
                "ratio_2019": ratio_2019,
                "reason": "Division by zero while calculating the change ratio.",
                "output_meta": {"currency": None, "scale": None, "unit": "percentage"},
            },
        }

    change_ratio = (ratio_2019 - ratio_2018) / ratio_2018
    return {
        "value": change_ratio * 100,
        "trace": {
            "ratio_2018": ratio_2018,
            "ratio_2019": ratio_2019,
            "change_ratio": change_ratio,
            "output_meta": {"currency": None, "scale": None, "unit": "percentage"},
        },
    }

